import math, mpmath
from sympy import factorint, primerange
c0=float(-4*mpmath.zeta(-0.5))
def A(p): return 1-3/p**2+2/p**3
def B(p): return (p-1)*(p*p-2+math.sqrt(p))/p**3
def D(p): return (p-1)**2*(p+1)/p**3
PR=list(primerange(2,200000))
logAall=sum(math.log(A(p)) for p in PR)
def h(q):
    fa=factorint(q); s=logAall
    for p,v in fa.items():
        s+= math.log((B(p) if v==1 else D(p)))-math.log(A(p)) if p<200000 else math.log((B(p) if v==1 else D(p)))
    return c0*math.exp(s)
def rho(f,m): return sum(1 for a in range(m) if f(a)%m==0)
def Cf(f):
    s=0
    for p in PR:
        if p<300:
            x=rho(f,p)/p; z=rho(f,p*p)/p**2
        else:
            x=rho(f,p)/p if p<3000 else None
            if x is None: s+=math.log(A(p)); continue  # crude
            z=x/p  # approx
        s+=math.log(A(p)*(1-x)+B(p)*(x-z)+D(p)*z)
    return 2/3*c0*math.exp(s)
import sys
for name,f,fp in [("2t",lambda t:2*t,lambda t:2),("4t^2+4",lambda t:4*t*t+4,lambda t:8*t),("t^2+t+2",lambda t:t*t+t+2,lambda t:2*t+1)]:
    C=Cf(f)
    for y in [200,1000,3000]:
        S=sum(fp(k)*math.sqrt(f(k))*h(f(k)) for k in range(1,y+1))
        Y=f(y); print(name,y,S/(C*Y**1.5), (S-C*Y**1.5)/(Y**1.5*y**-0.5))
EOF
